#include <memory>
#include <iostream>

int main() {
    int* p1 = new int(42);
    std::auto_ptr<int> ap(p1);

    // 1. Deletes p1
    // 2. Adopts nullptr
    ap.reset(); 

    // --- DANGER ZONE ---
    // int* p_array = new int[10];
    // std::auto_ptr<int> ap_bad(p_array); 
    // ap_bad will call 'delete p_array' instead of 'delete[] p_array'
    // This is UNDEFINED BEHAVIOR and likely causes memory corruption.

    std::auto_ptr<int> ap2(new int(5));
    int* p3 = new int(10);
    ap2.reset(p3); // Deletes 5, adopts 10.
}
